insert into storage.buckets (id,name,public,file_size_limit,allowed_mime_types) values ('product-images','product-images',true,5242880,array['image/jpeg','image/png','image/webp']) on conflict (id) do update set public=true,file_size_limit=5242880,allowed_mime_types=array['image/jpeg','image/png','image/webp'];
create table if not exists public.product_images(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products(id) on delete cascade,storage_path text not null unique,alt_text text,sort_order integer not null default 0,is_primary boolean not null default false,created_at timestamptz not null default now());
alter table public.product_images enable row level security;
grant select on public.product_images to anon,authenticated; grant insert,update,delete on public.product_images to authenticated;
drop policy if exists product_images_public_select on public.product_images; create policy product_images_public_select on public.product_images for select using(true);
drop policy if exists product_images_seller_insert on public.product_images; create policy product_images_seller_insert on public.product_images for insert to authenticated with check(exists(select 1 from public.products p join public.profiles pr on pr.id=(select auth.uid()) where p.id=product_id and (pr.role='admin' or p.seller_id=(select auth.uid()))) and split_part(storage_path,'/',1)=(select auth.uid())::text);
drop policy if exists product_images_seller_update on public.product_images; create policy product_images_seller_update on public.product_images for update to authenticated using(exists(select 1 from public.products p join public.profiles pr on pr.id=(select auth.uid()) where p.id=product_id and (pr.role='admin' or p.seller_id=(select auth.uid())))) with check(exists(select 1 from public.products p join public.profiles pr on pr.id=(select auth.uid()) where p.id=product_id and (pr.role='admin' or p.seller_id=(select auth.uid()))));
drop policy if exists product_images_seller_delete on public.product_images; create policy product_images_seller_delete on public.product_images for delete to authenticated using(exists(select 1 from public.products p join public.profiles pr on pr.id=(select auth.uid()) where p.id=product_id and (pr.role='admin' or p.seller_id=(select auth.uid()))));
drop policy if exists product_images_upload on storage.objects; create policy product_images_upload on storage.objects for insert to authenticated with check(bucket_id='product-images' and (storage.foldername(name))[1]=(select auth.uid())::text);
drop policy if exists product_images_update on storage.objects; create policy product_images_update on storage.objects for update to authenticated using(bucket_id='product-images' and (storage.foldername(name))[1]=(select auth.uid())::text) with check(bucket_id='product-images' and (storage.foldername(name))[1]=(select auth.uid())::text);
drop policy if exists product_images_delete on storage.objects; create policy product_images_delete on storage.objects for delete to authenticated using(bucket_id='product-images' and (storage.foldername(name))[1]=(select auth.uid())::text);
create index if not exists product_images_product_sort_idx on public.product_images(product_id,sort_order,created_at); create unique index if not exists product_images_one_primary_idx on public.product_images(product_id) where is_primary=true;